type ConsultDoctorListResetListener = () => void;

const resetListeners = new Set<ConsultDoctorListResetListener>();
let pendingDoctorListReset = false;

export const requestConsultDoctorListReset = (): void => {
  pendingDoctorListReset = true;
  resetListeners.forEach((listener: ConsultDoctorListResetListener): void => {
    listener();
  });
};

export const subscribeConsultDoctorListReset = (
  listener: ConsultDoctorListResetListener
): (() => void) => {
  resetListeners.add(listener);

  return (): void => {
    resetListeners.delete(listener);
  };
};

export const consumeConsultDoctorListReset = (): boolean => {
  const shouldReset = pendingDoctorListReset;
  pendingDoctorListReset = false;

  return shouldReset;
};

